<?php require 'config/bootstrap.php'; require_login(); require 'services/Analyzer.php'; $id=(int)($_GET['id']??0); $c=own_contract($id); $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){ csrf_check(); $do=$_POST['do']??'';
 if($do==='run'){ $v=$pdo->prepare("SELECT * FROM contract_versions WHERE contract_id=? AND extraction_status IN('success','manual') ORDER BY id DESC LIMIT 1");$v->execute([$id]);$ver=$v->fetch();
  if(!$ver) flash('No version with extracted text. Upload a readable document or paste text first.','error'); else { try{ [$a,$b]=run_analysis($pdo,$id,$ver); log_act('analysis_run',$id,"$a clauses, $b suggestions"); flash("Heuristic analysis done: $a clauses, $b obligation suggestions."); }catch(Throwable $e){ error_log($e->getMessage()); flash('Analysis failed: '.($e instanceof RuntimeException?$e->getMessage():'internal error'),'error'); } } }
 elseif($do==='confirm'||$do==='reject'){ $sid=(int)$_POST['sid']; $s=$pdo->prepare("SELECT * FROM obligation_suggestions WHERE id=? AND contract_id=? AND review_status='pending'");$s->execute([$sid,$id]);$sg=$s->fetch();
  if($sg){ if($do==='confirm'){ $d=trim($_POST['description']??''); if($d===''){flash('Description required.','error');header("Location: analysis.php?id=$id");exit;} $pdo->beginTransaction(); $pdo->prepare('INSERT INTO obligations(contract_id,suggestion_id,description,responsible_party,due_date,notes) VALUES(?,?,?,?,?,?)')->execute([$id,$sid,mb_substr($d,0,500),trim($_POST['party']??''),valid_date($_POST['due_date']??''),trim($_POST['notes']??'')]); $pdo->prepare("UPDATE obligation_suggestions SET review_status='confirmed' WHERE id=?")->execute([$sid]); $pdo->commit(); log_act('suggestion_confirmed',$id); flash('Obligation confirmed.'); }
   else { $pdo->prepare("UPDATE obligation_suggestions SET review_status='rejected' WHERE id=?")->execute([$sid]); log_act('suggestion_rejected',$id); flash('Suggestion rejected.'); } } }
 elseif($do==='finding'&&in_array($_POST['rs']??'',['open','accepted','dismissed'],true)){ $pdo->prepare('UPDATE risk_findings SET review_status=? WHERE id=? AND contract_id=?')->execute([$_POST['rs'],(int)$_POST['fid'],$id]); flash('Finding updated.'); }
 header("Location: analysis.php?id=$id"); exit; }
$f=$pdo->prepare('SELECT * FROM risk_findings WHERE contract_id=? ORDER BY FIELD(level,"high","medium","low")');$f->execute([$id]);$finds=$f->fetchAll();
$cl=$pdo->prepare('SELECT category,COUNT(*) n FROM clauses WHERE contract_id=? GROUP BY category ORDER BY n DESC');$cl->execute([$id]);$cls=$cl->fetchAll();
$sg=$pdo->prepare("SELECT * FROM obligation_suggestions WHERE contract_id=? AND review_status='pending'");$sg->execute([$id]);$sugs=$sg->fetchAll();
$ar=$pdo->prepare('SELECT created_at,provider FROM analysis_results WHERE contract_id=? ORDER BY id DESC LIMIT 1');$ar->execute([$id]);$last=$ar->fetch();
$pl=['financial'=>'Financial and liability','termination'=>'Termination and lock-in','privacy'=>'Privacy and data security','ip'=>'Intellectual property'];
page_head('Analysis'); ?><a href="contract.php?id=<?=$id?>">&larr; <?=e($c['title'])?></a><h1 class="h3 my-3">Analysis</h1>
<div class="alert alert-secondary">Heuristic, keyword-rule analysis. No LLM or trained model is used; findings are informational, not legal advice. Scoring: per pillar, sum of matched-pattern weights (1-2 low, 3-4 medium, 5+ high). A pillar with no match gets no finding, which does not mean it is risk-free.</div>
<form method="post" class="mb-3"><?=csrf_field()?><input type="hidden" name="do" value="run"><button class="btn btn-primary">Run analysis on latest version</button> <span class="text-muted"><?=$last?'Last run '.e($last['created_at']):'Not run yet'?></span></form>
<div class="cardx mb-3"><h2 class="h6">Risk findings</h2><?php if(!$finds):?><div class="empty">No findings<?=$last?' matched the rules.':'. Run the analysis first.'?></div><?php endif; foreach($finds as $x):?><div class="border-top py-2" style="border-color:var(--border)!important"><span class="badge bg-<?=['high'=>'danger','medium'=>'warning text-dark','low'=>'success'][$x['level']]?>"><?=e($x['level'])?></span> <strong><?=e($pl[$x['pillar']])?></strong><p class="mb-1"><?=e($x['explanation'])?></p><details><summary class="text-muted">Evidence from document</summary><pre class="doc"><?=e($x['evidence'])?></pre></details>
<form method="post" class="d-flex gap-1"><?=csrf_field()?><input type="hidden" name="do" value="finding"><input type="hidden" name="fid" value="<?=$x['id']?>"><select name="rs" class="form-select form-select-sm w-auto"><?php foreach(['open','accepted','dismissed'] as $s):?><option <?=$x['review_status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="btn btn-sm btn-outline-light">Save</button></form></div><?php endforeach;?></div>
<div class="cardx mb-3"><h2 class="h6">Clause categories (heuristic)</h2><?php if(!$cls):?><div class="empty">None yet.</div><?php else: foreach($cls as $x):?><span class="badge bg-secondary me-1"><?=e($x['category'])?> · <?=$x['n']?></span><?php endforeach; endif;?></div>
<div class="cardx"><h2 class="h6">Suggested obligations, pending your review</h2><p class="text-muted">Suggestions are not facts. Only confirmed ones become obligations. Dates are filled only when written explicitly in the text; relative deadlines are shown as triggers.</p><?php if(!$sugs):?><div class="empty">No pending suggestions.</div><?php endif; foreach($sugs as $x):?>
<form method="post" class="border-top py-2 row g-2" style="border-color:var(--border)!important"><?=csrf_field()?><input type="hidden" name="sid" value="<?=$x['id']?>"><div class="col-12"><textarea class="form-control" name="description" rows="2"><?=e($x['description'])?></textarea></div>
<div class="col-md-3"><input class="form-control" name="party" placeholder="Responsible" value="<?=e($x['responsible_party'])?>"></div><div class="col-md-3"><input class="form-control" type="date" name="due_date" value="<?=e($x['due_date'])?>"></div><div class="col-md-3"><input class="form-control" name="notes" placeholder="Notes"></div>
<div class="col-md-3"><button name="do" value="confirm" class="btn btn-sm btn-primary">Confirm</button> <button name="do" value="reject" class="btn btn-sm btn-outline-danger" formnovalidate>Reject</button></div><?php if($x['trigger_text']):?><div class="col-12 text-muted">Trigger found: <?=e($x['trigger_text'])?></div><?php endif;?></form><?php endforeach;?></div><?php page_foot();
